theorem black_run_le (H : Hyp F n c ε) {j : ℕ} {l : ℤ} {t : ℕ}
    (h2j : 2 * j + 2 * F.edgeB + 2 ≤ n) (hb : ∀ i : ℕ, i ≤ t → F.black n c ε j (l + i)) :
