theorem blk_of_notMem_whiteStrip {half : ℕ} {σ : ℝ} (T : F.TriFam half σ) {q : ℕ × ℤ}
    (h1 : 1 ≤ q.1) (h2 : q.1 ≤ half) (h : q ∉ whiteStrip half T.W) :
    (q.1 - 1, q.2) ∈ T.blk

theorem encChainX_den_pos {κ p₀ : ℝ}
    (hsmall : (1 - p₀) * (Real.exp κ + 1) ≤ 1) :
    0 < 1 - (1 - p₀) * Real.exp κ

theorem encChainX_fixed {κ p₀ : ℝ}
    (hsmall : (1 - p₀) * (Real.exp κ + 1) ≤ 1) :
    p₀ + (1 - p₀) * Real.exp κ * encChainX κ p₀ = encChainX κ p₀

theorem not_mem_both {half : ℕ} {σ : ℝ} (T : F.TriFam half σ) (hσ : 0 < σ)
    {t t' : ℕ × ℤ × ℝ} (ht : t ∈ T.T) (ht' : t' ∈ T.T) (hne : t ≠ t') {y : ℕ × ℤ}
    (hy : y ∈ F.triangle t.1 t.2.1 t.2.2) (hy' : y ∈ F.triangle t'.1 t'.2.1 t'.2.2) : False

theorem abs_fint_le_sum {k n : ℕ} (a : Fin k → ℕ) (R : Fin n → ℤ) {B : ℤ}
    (hB : ∀ m, |R m| ≤ B) :
    |F.fint a R| ≤ B * ∑ m : Fin n, (F.q : ℤ) ^ (n - 1 - (m : ℕ)) * (F.p : ℤ) ^ pre a m

